<script setup>
import { localTime } from './api'
defineProps({item:{type:Object,required:true}})
</script>
<template><details class="screenshot-metadata"><summary>Image information</summary><dl><template v-if="item.deleted"><dt>Deletion</dt><dd>{{localTime(item.deleted_at)}} · {{item.deleted_by_name || item.deleted_by || "Employee"}}</dd><dt>Reason</dt><dd>{{item.deleted_reason || "Not provided"}}</dd><dt>Storage cleanup</dt><dd>{{item.deletion_cleanup_pending?"Pending — original hidden":"Complete"}} · Neutral deletion, no score changes</dd></template><dt>Employee</dt><dd>{{item.user_name || 'You'}} · {{item.employee_id}}</dd><dt>Device</dt><dd>{{item.device_name}} · {{item.device_id}}</dd><dt>Captured / received</dt><dd>{{localTime(item.captured_at)}} / {{localTime(item.received_at)}}</dd><dt>Application / title</dt><dd>{{item.app_name || 'Unknown'}} · {{item.window_title || 'Unavailable'}}</dd><dt>URL</dt><dd>{{item.url || 'Not collected / unavailable'}}</dd><dt>Image</dt><dd>{{item.width && item.height?item.width+' × '+item.height:'Dimensions unavailable for older image'}} · {{item.bytes ?? 'Unknown'}} bytes · {{item.mime_type || 'image/png'}}</dd><dt>Capture state (agent reported)</dt><dd>{{item.capture_state || 'Not reported by older agent'}} · Seconds without input: {{item.idle_seconds ?? 'unknown'}} · Idle threshold: {{item.idle_threshold_seconds ?? 'unknown'}} seconds</dd><dt>Agent version</dt><dd>{{item.agent_version || 'Not reported'}}</dd><dt>SHA-256 (server calculated)</dt><dd>{{item.sha256 || 'Unavailable'}}</dd><dt>Event ID</dt><dd>{{item.event_id}}</dd></dl></details></template>
<style scoped>.screenshot-metadata{padding:16px;background:#f4f8f7;color:#183b3c}.screenshot-metadata summary{cursor:pointer;font-weight:650}.screenshot-metadata dl{display:grid;grid-template-columns:minmax(120px,1fr) 3fr;gap:10px}.screenshot-metadata dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap}.screenshot-metadata dt{font-weight:600}@media(max-width:600px){.screenshot-metadata dl{grid-template-columns:1fr}.screenshot-metadata dd{margin-bottom:8px}}</style>
